import{g as a,ad as n,r as p,A as e}from"./chunks/framework.CK2aBVEu.js";const _=JSON.parse('{"title":"Composables","description":"","frontmatter":{},"headers":[],"relativePath":"docs/other/composables.md","filePath":"docs/other/composables.md","lastUpdated":1786369206000}'),l={name:"docs/other/composables.md"};function c(t,s,o,i,d,r){return n(),p("div",null,[...s[0]||(s[0]=[e(`<h1 id="composables" tabindex="-1">Composables <a class="header-anchor" href="#composables" aria-label="Permalink to “Composables”">​</a></h1><p>Composition API helpers that don&#39;t belong to one component.</p><h2 id="usepagemeta" tabindex="-1">usePageMeta <a class="header-anchor" href="#usepagemeta" aria-label="Permalink to “usePageMeta”">​</a></h2><p>Keeps <code>document.title</code> (and the favicon) in sync with reactive state. Call it once per page component; it watches the function you pass and re-applies the result whenever a dependency changes.</p><div class="language-vue"><button title="Copy Code" class="copy"></button><span class="lang">vue</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">script</span><span class="s_1i4ay4"> setup</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_edvzsf">import</span><span class="s_13ahmt"> { </span><span class="s_4q1z3w">ref</span><span class="s_13ahmt"> }</span><span class="s_edvzsf"> from</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">vue</span><span class="s_w1p9wo">&#39;</span></span>
<span class="line"><span class="s_edvzsf">import</span><span class="s_13ahmt"> { </span><span class="s_4q1z3w">usePageMeta</span><span class="s_13ahmt"> }</span><span class="s_edvzsf"> from</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">frappe-ui</span><span class="s_w1p9wo">&#39;</span></span>
<span class="line"></span>
<span class="line"><span class="s_252irl">const</span><span class="s_295sjd"> title</span><span class="s_2ekfrt"> =</span><span class="s_indoxt"> ref</span><span class="s_13ahmt">(</span><span class="s_w1p9wo">&#39;</span><span class="s_2575z4">Loading…</span><span class="s_w1p9wo">&#39;</span><span class="s_13ahmt">)</span></span>
<span class="line"></span>
<span class="line"><span class="s_indoxt">usePageMeta</span><span class="s_13ahmt">(()</span><span class="s_50ecpt"> =&gt;</span><span class="s_13ahmt"> ({</span></span>
<span class="line"><span class="s_r4oegk">  title</span><span class="s_1jjt6x">:</span><span class="s_22m8k2"> title</span><span class="s_1jjt6x">.</span><span class="s_11933w">value</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_r4oegk">  emoji</span><span class="s_1jjt6x">:</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">🌈</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_13ahmt">}))</span></span>
<span class="line"><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">script</span><span class="s_1zd9e2">&gt;</span></span></code></pre></div><p>The function returns <code>null</code>/<code>undefined</code> to skip an update, or a <code>PageMeta</code> object:</p><ul><li><code>title</code> — sets <code>document.title</code>.</li><li><code>icon</code> — a URL to a favicon image.</li><li><code>emoji</code> — renders the emoji as the favicon, taking priority over <code>icon</code>.</li><li>Omitting both <code>icon</code> and <code>emoji</code> restores the page&#39;s original favicon.</li></ul><p>Called inside a component, the watcher stops automatically on unmount — there is nothing to clean up. Called outside one (a router hook, a plain module), it returns a stop function:</p><div class="language-js"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_252irl">const</span><span class="s_295sjd"> stop</span><span class="s_2ekfrt"> =</span><span class="s_indoxt"> usePageMeta</span><span class="s_13ahmt">(()</span><span class="s_50ecpt"> =&gt;</span><span class="s_13ahmt"> ({</span><span class="s_r4oegk"> title</span><span class="s_1jjt6x">:</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">Loading…</span><span class="s_w1p9wo">&#39;</span><span class="s_13ahmt"> }))</span></span>
<span class="line"><span class="s_1th9sy">// later</span></span>
<span class="line"><span class="s_indoxt">stop</span><span class="s_13ahmt">()</span></span></code></pre></div><h2 id="usecolorscheme" tabindex="-1">useColorScheme <a class="header-anchor" href="#usecolorscheme" aria-label="Permalink to “useColorScheme”">​</a></h2><p>The app&#39;s light/dark preference, shared by every caller. The first call restores the saved preference and starts following the OS setting — there is nothing to install.</p><div class="language-vue"><button title="Copy Code" class="copy"></button><span class="lang">vue</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">script</span><span class="s_1i4ay4"> setup</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_edvzsf">import</span><span class="s_13ahmt"> { </span><span class="s_4q1z3w">useColorScheme</span><span class="s_13ahmt"> }</span><span class="s_edvzsf"> from</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">frappe-ui</span><span class="s_w1p9wo">&#39;</span></span>
<span class="line"></span>
<span class="line"><span class="s_252irl">const</span><span class="s_1jjt6x"> {</span><span class="s_295sjd"> colorScheme</span><span class="s_1jjt6x">,</span><span class="s_295sjd"> setColorScheme</span><span class="s_1jjt6x">,</span><span class="s_295sjd"> toggleColorScheme</span><span class="s_1jjt6x"> }</span><span class="s_2ekfrt"> =</span><span class="s_indoxt"> useColorScheme</span><span class="s_13ahmt">()</span></span>
<span class="line"><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">script</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">template</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_1zd9e2">  &lt;</span><span class="s_1uuh8p">button</span><span class="s_1i4ay4"> @click</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">toggleColorScheme</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_6am9cx">    {{ colorScheme }}</span></span>
<span class="line"><span class="s_1zd9e2">  &lt;/</span><span class="s_1uuh8p">button</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">template</span><span class="s_1zd9e2">&gt;</span></span></code></pre></div><ul><li><code>colorScheme</code> — <code>Ref&lt;&#39;light&#39; | &#39;dark&#39; | &#39;system&#39;&gt;</code>, read-only. It, the <code>&lt;html data-theme&gt;</code> attribute, and the saved preference always move together, so write through <code>setColorScheme</code> rather than assigning the ref.</li><li><code>setColorScheme(scheme)</code> — selects a preference: applies <code>data-theme</code> and persists it.</li><li><code>toggleColorScheme()</code> — flips between light and dark.</li></ul><p>Switching schemes would otherwise cross-fade every transitioning surface at once, which reads as a flash. To suppress it, <code>useColorScheme</code> puts a <code>no-transition</code> class on <code>&lt;html&gt;</code> for the two frames around the swap; the rule that acts on it ships in <code>frappe-ui/style.css</code>. Apps that don&#39;t load that stylesheet still switch correctly — they just see the cross-fade.</p><h2 id="shellscrollcontainer-useshellscrolled" tabindex="-1">shellScrollContainer / useShellScrolled <a class="header-anchor" href="#shellscrollcontainer-useshellscrolled" aria-label="Permalink to “shellScrollContainer / useShellScrolled”">​</a></h2><p><code>shellScrollContainer</code> is a computed ref pointing at the scroll element of the mounted <a href="./../components/desktopshell"><code>DesktopShell</code> or <code>MobileShell</code></a> — <code>null</code> when neither is mounted. Read <code>scrollTop</code> off it, or call <code>scrollTo</code>/<code>scrollBy</code> directly, from anywhere — a component, a <code>vue-router</code> <code>scrollBehavior</code>, a navigation guard.</p><div class="language-vue"><button title="Copy Code" class="copy"></button><span class="lang">vue</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">script</span><span class="s_1i4ay4"> setup</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_edvzsf">import</span><span class="s_13ahmt"> { </span><span class="s_4q1z3w">shellScrollContainer</span><span class="s_13ahmt"> }</span><span class="s_edvzsf"> from</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">frappe-ui</span><span class="s_w1p9wo">&#39;</span></span>
<span class="line"></span>
<span class="line"><span class="s_50ecpt">function</span><span class="s_indoxt"> scrollToTop</span><span class="s_13ahmt">()</span><span class="s_13ahmt"> {</span></span>
<span class="line"><span class="s_22m8k2">  shellScrollContainer</span><span class="s_1jjt6x">.</span><span class="s_11933w">value</span><span class="s_1jjt6x">?.</span><span class="s_indoxt">scrollTo</span><span class="s_13ahmt">({ </span><span class="s_r4oegk">top</span><span class="s_1jjt6x">:</span><span class="s_40mev6"> 0</span><span class="s_1jjt6x">,</span><span class="s_r4oegk"> behavior</span><span class="s_1jjt6x">:</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">smooth</span><span class="s_w1p9wo">&#39;</span><span class="s_13ahmt"> })</span></span>
<span class="line"><span class="s_13ahmt">}</span></span>
<span class="line"><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">script</span><span class="s_1zd9e2">&gt;</span></span></code></pre></div><p><code>useShellScrolled</code> tracks whether that container is scrolled past a threshold — the usual driver of a header&#39;s border or shadow appearing on scroll. It follows the active shell automatically across a desktop/mobile layout swap.</p><div class="language-vue"><button title="Copy Code" class="copy"></button><span class="lang">vue</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">script</span><span class="s_1i4ay4"> setup</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_edvzsf">import</span><span class="s_13ahmt"> { </span><span class="s_4q1z3w">useShellScrolled</span><span class="s_13ahmt"> }</span><span class="s_edvzsf"> from</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">frappe-ui</span><span class="s_w1p9wo">&#39;</span></span>
<span class="line"></span>
<span class="line"><span class="s_252irl">const</span><span class="s_295sjd"> scrolled</span><span class="s_2ekfrt"> =</span><span class="s_indoxt"> useShellScrolled</span><span class="s_13ahmt">({</span><span class="s_r4oegk"> threshold</span><span class="s_1jjt6x">:</span><span class="s_40mev6"> 12</span><span class="s_13ahmt"> })</span></span>
<span class="line"><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">script</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">template</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_1zd9e2">  &lt;</span><span class="s_1uuh8p">header</span><span class="s_1i4ay4"> :data-scrolled</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">scrolled</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2">&gt;</span><span class="s_6am9cx">…</span><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">header</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">template</span><span class="s_1zd9e2">&gt;</span></span></code></pre></div><p><code>threshold</code> defaults to <code>200</code>. Without a mounted shell, <code>scrolled</code> stays <code>false</code> and the composable warns once in development.</p><h2 id="useshortcut" tabindex="-1">useShortcut <a class="header-anchor" href="#useshortcut" aria-label="Permalink to “useShortcut”">​</a></h2><p>Registers a global keyboard shortcut for as long as the calling component is mounted — no manual <code>keydown</code> listener, no cleanup to remember.</p><div class="language-vue"><button title="Copy Code" class="copy"></button><span class="lang">vue</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">script</span><span class="s_1i4ay4"> setup</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_edvzsf">import</span><span class="s_13ahmt"> { </span><span class="s_4q1z3w">useShortcut</span><span class="s_13ahmt"> }</span><span class="s_edvzsf"> from</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">frappe-ui</span><span class="s_w1p9wo">&#39;</span></span>
<span class="line"></span>
<span class="line"><span class="s_indoxt">useShortcut</span><span class="s_13ahmt">({</span></span>
<span class="line"><span class="s_r4oegk">  key</span><span class="s_1jjt6x">:</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">k</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_r4oegk">  ctrl</span><span class="s_1jjt6x">:</span><span class="s_40mev6"> true</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_r4oegk">  description</span><span class="s_1jjt6x">:</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">Open command palette</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_r4oegk">  group</span><span class="s_1jjt6x">:</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">General</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_indoxt">  handler</span><span class="s_1jjt6x">:</span><span class="s_13ahmt"> ()</span><span class="s_50ecpt"> =&gt;</span><span class="s_indoxt"> open</span><span class="s_13ahmt">()</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_13ahmt">})</span></span>
<span class="line"><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">script</span><span class="s_1zd9e2">&gt;</span></span></code></pre></div><p>Full option reference, plus <code>getActiveShortcuts</code> and <code>formatShortcutLabel</code>, are documented on <a href="./../components/keyboardshortcutsmodal"><code>KeyboardShortcutsModal</code></a> — the component that renders whatever <code>useShortcut</code> has registered as a searchable cheat sheet.</p>`,24)])])}const u=a(l,[["render",c]]);export{_ as __pageData,u as default};
